using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text.Json.Serialization.Metadata;

// --- Set up options with a known type resolver ---
var options = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};

// 1) Strongly-typed retrieval: GetTypeInfo returns JsonTypeInfo (non-generic),
//    but you can cast to JsonTypeInfo<T> to stay strongly-typed.
JsonTypeInfo<Person> personInfo =
    (JsonTypeInfo<Person>)options.GetTypeInfo(typeof(Person));

Console.WriteLine($"Got typed metadata for: {personInfo.Type.Name}");
Console.WriteLine($"  Kind          : {personInfo.Kind}");
Console.WriteLine($"  Properties    : {personInfo.Properties.Count}");

string json = JsonSerializer.Serialize(new Person("Ada", 36), personInfo);
Console.WriteLine($"  Round-trip    : {json}");

// 2) Probe without throwing using TryGetTypeInfo (added in .NET 9).
//    Returns false instead of throwing when metadata isn't available.
if (options.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? found))
{
    Console.WriteLine($"\nTryGetTypeInfo(Person)  → found ({found!.Type.Name})");
}

// Use a resolver that only knows about Person — Widget will be unknown.
var limited = new JsonSerializerOptions
{
    TypeInfoResolver = JsonTypeInfoResolver.Combine(
        new WidgetContext())          // only exposes Widget
};

if (limited.TryGetTypeInfo(typeof(Person), out _))
    Console.WriteLine("TryGetTypeInfo(Person)  → found  (unexpected)");
else
    Console.WriteLine($"\nTryGetTypeInfo(Person) on limited resolver → not found (no exception!)");

if (limited.TryGetTypeInfo(typeof(Widget), out JsonTypeInfo? widgetInfo))
    Console.WriteLine($"TryGetTypeInfo(Widget) on limited resolver → found ({widgetInfo!.Type.Name})");

public record Person(string Name, int Age);

public record Widget(int Id);

[JsonSerializable(typeof(Widget))]
internal partial class WidgetContext : JsonSerializerContext;

